    int n;
    while (true) {
        scanf("%d %d", &w, &h);
        if (w + h == 0) break;
        scanf("%d", &n);
        vector<int> x1(n), x2(n), y1(n), y2(n);

        // Reserve space for coordinates to avoid repeated allocations
        vector<int> x, y;
        x.reserve(n * 2 + 4);
        y.reserve(n * 2 + 4);

        for(int i = 0; i < n; i++) {
            scanf("%d %d %d %d", &x1[i], &y1[i], &x2[i], &y2[i]);
            x.pb(x1[i]); y.pb(y1[i]); x.pb(x2[i]); y.pb(y2[i]);
        }
        x.pb(0); x.pb(w); y.pb(0); y.pb(h);

        sort(all(x)); sort(all(y));
        x.erase(unique(all(x)), x.end()); y.erase(unique(all(y)));

